export const LEVEL_COUNT = LEVELS.length;
export function getLevel(id, {tutorial = false} = {}) {
  if (!Number.isInteger(id) || id < 1 || id > LEVEL_COUNT) throw new RangeError(`Unknown level: ${id}`);
  const source = id === 1 && tutorial ? TUTORIAL_LEVEL : LEVELS[id - 1];
  return typeof structuredClone === 'function' ? structuredClone(source) : JSON.parse(JSON.stringify(source));
}
